\begin{aligned}
&\text{寻找 } \vec{w}, \text{ 以及 } \xi_{i,j} \ge 0 \text{ 使得：} \\
&\bullet \frac{1}{2}\vec{w}^T\vec{w} + C \sum_{i,j} \xi_{i,j} \text{ 最小化} \\
&\bullet \text{并且对于所有 } \{\Phi(d_i, d_j, q) : d_i \prec d_j\}, \vec{w}^T\Phi(d_i, d_j, q) \ge 1 - \xi_{i,j}
\end{aligned}
\tag{15.20}
